head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _4 : dummy_reqdn (다운로드 요청 관련 옵션) 계열 중 서버 연계 옵션 - lazyInfoArr / optionParam / msaName
//     description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "lazyInfoArr(선택) 파라미터로 infoArray 파라미터에 설정한 추가 정보의 출력 순서를 설정합니다.",
        "lazyInfoArr(선택) 파라미터를 'true' 로 설정 시 Excel 파일에 가장 마지막에 출력합니다.",
        "lazyInfoArr(선택) 파라미터를 'false' 로 설정 시 Excel 파일에 가장 먼저 출력합니다.",
        "lazyInfoArr(선택) 파라미터는 데이터 영역과 겹칠 경우 최종적으로 어떤 값이 출력되는지 결과가 달라지며, 'false' 설정 시 infoArray 파라미터에 의해 병합된 셀은 해제되지 않으므로 주의해야 합니다.",
        "lazyInfoArr(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "optionParam(선택) 파라미터로 파일 암호화(DRM) 연계 시 사용자 정의 Class 에 HashMap 인자로 전달할 값을 설정합니다.",
        "optionParam(선택) 파라미터값은 서버에서 'optionParam' 키로 참조됩니다.",
        "optionParam(선택) 파라미터를 생략하면 기본값 빈 문자열('')이 적용됩니다.",
        "msaName(선택) 파라미터로 MSA 기능을 사용하는 경우 적용할 MSA 서버의 이름을 설정합니다.",
        "msaName(선택) 파라미터에 msaName 이 지정된 경우 해당 MSA 서버의 경로가 자동으로 URL 에 추가됩니다.",
        "msaName(선택) 파라미터를 생략하면 기본값 빈 문자열('')이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 데이터 4행(col1_1 ~ col4_4)이 바인딩되어 있음\n- lazyInfoArr 검증을 위해 데이터 영역과 겹치는 추가 정보(infoArray) 1건을 항상 함께 전달함 (rowIndex=1, colIndex=0, rowSpan=2, colSpan=2, text=INFO / Excel 의 2행 A열 ~ 3행 B열 = 데이터 col1_1, col2_1, col1_2, col2_2 영역과 겹침)\n- 다운로드 파일은 내용 확인이 쉽도록 확장자를 xlsx 로 고정함\n[절차]\n1. par 옵션(lazyInfoArr / optionParam / msaName) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭한다\n[확인]\n- 결과창에 전달 옵션 / 요청 방식과 요청 URL / 서버로 전달된 lazyInfoArr, optionParam, msaName 값이 출력됨\n- 다운로드된 Excel 파일을 열어 겹친 셀(2행 A열 ~ 3행 B열)에 남은 최종 값과 병합 유지 여부를 확인\n- optionParam 은 서버측 사용자 정의 DRM Class 가, msaName 은 MSA 서버 구성이 있어야 실제 파일 효과가 나타나므로 서버 전달값과 요청 URL 로 확인"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩)
    let cList = $c.gcm.createCList({
        dataList: "data:" + dlt_bind.id
    });
    await $c.gcm.createBasicGridView(cList);
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · extension 은 담당 옵션이 아니며 파일 내용 확인 편의를 위해 항상 xlsx 로 고정한다.
//  · 엔진이 호출 중 options 객체에 내부 키(cellInfo, scope, isBasicCol 등)를 덧붙이므로 전달값 문자열은 호출 전에 미리 만들어 둔다.
scwin.buildOptions = function () {
    let options = { "extension" : "xlsx" };
    let arrDesc = [];

    let fnSet = function (sKey, vValue) {
        options[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_lazyInfoArr.getValue(); if (v !== "") fnSet("lazyInfoArr", v);
    v = par_optionParam.getValue(); if (v !== "") fnSet("optionParam", v);
    v = par_msaName.getValue();     if (v !== "") fnSet("msaName", v);

    return { "options" : options, "desc" : ((arrDesc.length === 0) ? "3개 옵션 전체 생략" : arrDesc.join(" / ")) };
}



// 다운로드 요청 캡처 : 요청 방식(Form Submit / XHR), 요청 URL, 서버로 전달된 값을 확인하기 위해
//  메소드 호출 구간에서만 form submit 과 XHR send 를 감싸고 호출 직후 원복한다. (실제 요청은 그대로 통과시킨다.)
scwin.hookRequest = function () {
    let objReq = { "kind" : "", "url" : "", "body" : "" };
    scwin.gVar = { "req" : objReq };

    let fnSubmit = HTMLFormElement.prototype.submit;
    let fnOpen = XMLHttpRequest.prototype.open;
    let fnSend = XMLHttpRequest.prototype.send;

    HTMLFormElement.prototype.submit = function () {
        if (objReq.kind === "") {
            objReq.kind = "Form Submit (iframe 전송)";
            objReq.url = this.action;
            let objInput = this.querySelector("input[name=xmlValue]");
            objReq.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };
    XMLHttpRequest.prototype.open = function (sMethod, sUrl) {
        this.wqTestUrl = sUrl;
        return fnOpen.apply(this, arguments);
    };
    XMLHttpRequest.prototype.send = function (vData) {
        if (objReq.kind === "") {
            objReq.kind = "XHR (AJAX 전송)";
            objReq.url = this.wqTestUrl;
            objReq.body = vData + "";
        }
        return fnSend.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
        XMLHttpRequest.prototype.open = fnOpen;
        XMLHttpRequest.prototype.send = fnSend;
    };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
scwin.getSentValue = function (sKey) {
    let sBody = (scwin.gVar.req === undefined) ? "" : (scwin.gVar.req.body || "");
    let nKey = sBody.indexOf("hashkey='" + sKey + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// advancedExcelDownload 실행
//  · lazyInfoArr 은 infoArray 로 전달한 추가 정보의 출력 순서 옵션이므로 infoArray 를 항상 함께 전달한다.
//  · infoArray 는 데이터 영역과 겹치는 좌표로 고정하여 lazyInfoArr 값에 따른 최종 출력값 차이를 확인한다.
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    // 데이터 영역(Excel 2행 A열 ~ 3행 B열)과 겹치도록 고정한 추가 정보
    let infoArray = [ { "rowIndex" : 1, "colIndex" : 0, "rowSpan" : 2, "colSpan" : 2, "text" : "INFO" } ];

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(objBuild.options, infoArray);
    } finally {
        scwin.gVar.unhook();
    }

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);

    let objReq = scwin.gVar.req;
    if (objReq.kind === "") {
        bottom.setReturnValue("요청 발생 : 없음 (다운로드 미실행)");
        return;
    }

    bottom.setReturnValue("요청 방식 : " + objReq.kind + " / 요청 URL : " + objReq.url);
    bottom.setReturnValue("서버 전달값 : lazyInfoArr=" + scwin.getSentValue("lazyInfoArr") + " / optionParam=" + scwin.getSentValue("optionParam") + " / msaName=" + scwin.getSentValue("msaName"));
}
